with base as (select *, case when duration_sec >= 384 then 'High' when duration_sec >= 100 then 'Medium' else 'Low' end duration_sec_level from web_events where event_time >= timestamp '2023-05-06 07:00:00'), enriched as (select *, ntile(3) over (order by duration_sec desc, id) duration_sec_bucket, ntile(10) over (partition by session_id, event_type order by duration_sec, id) duration_sec_bucket_2, count(duration_sec) over w_ordered page_count_duration_sec from base window w_ordered as (partition by page)), prev_events as (select *, lag(event_time) over (partition by session_id order by event_time, id) as prev_event_time from enriched), gaps as (select *, case when prev_event_time is null or event_time > prev_event_time + interval '60' day then 1 else 0 end as new_group_flag from prev_events), sessionized as (select *, sum(new_group_flag) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as island_id from gaps), prev_events_2 as (select *, lag(event_time) over (partition by page order by event_time, id) as prev_event_time_2 from sessionized), gaps_2 as (select *, case when prev_event_time_2 is null or event_time > prev_event_time_2 + interval '14' day then 1 else 0 end as session_start_flag from prev_events_2), islands as (select *, sum(session_start_flag) over (partition by page order by event_time, id rows between unbounded preceding and current row) as session_no from gaps_2), joined as (select a.id, a.session_id, a.page, a.duration_sec_bucket, a.duration_sec_bucket_2, a.page_count_duration_sec, a.new_group_flag, a.prev_event_time_2, s.browser from islands a left join sessions s on a.session_id = s.id where s.started_at < '2023-10-01'), joined_web_events as (select src.id, src.session_id, src.page, src.new_group_flag, src.browser, b.browser as session_browser from joined src left join sessions b on src.session_id = b.id), deduped as (select * from (select *, row_number() over (partition by page, browser order by new_group_flag desc nulls last, id) as rn from joined_web_events) ranked where rn = 1), grouped as (select page, case when new_group_flag >= 1 then 'PREMIUM' else 'STANDARD' end as new_group_flag_tier, approx_percentile(new_group_flag, array(0.25, 0.5, 0.75)) as new_group_flag_quartiles, avg(new_group_flag) as avg_new_group_flag, sort_array(collect_set(session_browser)) as session_browser_list, sort_array(collect_set(page)) as page_list, grouping(page) as grouping_level from deduped group by rollup (page, case when new_group_flag >= 1 then 'PREMIUM' else 'STANDARD' end) having avg_new_group_flag > 0) select page, new_group_flag_tier, avg_new_group_flag, session_browser_list, page_list, grouping_level from grouped order by grouping_level nulls first, new_group_flag_tier;
